```xml
<?xml version="1.0" encoding="UTF-8" ?>
<!DOCTYPE mapper
  PUBLIC "-//mybatis.org//DTD Mapper 3.0//EN"
  "http://mybatis.org/dtd/mybatis-3-mapper.dtd">
<mapper namespace="mybatis1.mapper.StudentMapper">

  <!-- 파라미터 타입은 string, 반환은 DTO 타입 -->
  <select id="selectForName" parameterType="string" resultType="mybatis1.dto.StudentDTO1">
    SELECT
      student_id   AS no,
      name,
      department   AS majorName,
      gpa          AS score
    FROM students
    WHERE name = #{name}
  </select>

  <!--
    만약 부분 검색을 원하면 아래처럼 사용:
    WHERE name LIKE CONCAT('%', #{name}, '%')
  -->
</mapper>
```
